    /**
     * Tests getting all AccountStatements.
     *
     * @return    Collection
     */
    public List<AccountStatement> testGetAll() throws Throwable {
    LOGGER.info( "AccountStatementTest:testGetAll() - Retrieving Collection of AccountStatements:" );

    StringBuilder msg = new StringBuilder( "-- Failed to get all AccountStatement : " );
    List<AccountStatement> collection  = null;

    try {
        // call the static get method on the AccountStatementService
        collection = service.getAllAccountStatement();

        if ( collection == null || collection.size() == 0 ) {
            LOGGER.warning( unexpectedErrorMsg );
            LOGGER.warning( "-- " + msg.toString() + " Empty collection returned."  );
        }
        else {
            // Now print out the values
            AccountStatement currEntity  = null;
            Iterator<AccountStatement> iter = collection.iterator();

            while( iter.hasNext() ) {
                // Retrieve the entity
                currEntity = iter.next();

                assertNotNull( currEntity,"-- null value object in Collection." );
                assertNotNull( currEntity.getAccountStatementId(), "-- value object in Collection has a null primary key" );

                LOGGER.info( " - " + currEntity.toString() );
            }
        }
    }
    catch ( Throwable e ){
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() );

        throw e;
    }

    return( collection );
}

